from guide_dsl import *
# ============ Fluid Mechanics ============
G('fluids-a', 'Flow measurement', "Flow meters work by making the fluid trade pressure for speed and then measuring the pressure change. A Pitot tube points into the flow and stops a small stream of it; the extra pressure it reads is the velocity head. A venturi and an orifice plate squeeze the flow through a smaller opening and measure the pressure drop across it. || Real meters lose a little energy and the jet narrows, so a discharge coefficient below 1 corrects the ideal answer. Weirs measure open-channel flow from the height of water over a crest.",
  [('Pitot tube', r"V = \sqrt{2g × (stagnation head - static head)}"), ('Orifice discharging freely', r"Q = C_{d}A\sqrt{2gh}"), ('Venturi or orifice meter', r"Q = C_{d}A_{2}\sqrt{\frac{2g × head difference}{1 - (A_{2}/A_{1})^{2}}}")],
  ("A tank drains through a 20 mm hole 2 m below the water surface with a discharge coefficient of 0.62. Find the flow in L/s.", r"A = 0.000314 m^{2}. || Q = 0.62(0.000314)\sqrt{2(9.81)(2)} = 0.00122 m^{3}/s = 1.22 L/s.", 1.22, "0.62*(pi*0.02**2/4)*sqrt(2*g*2)*1000"),
  ["Leaving out the discharge coefficient.", "Using diameter where area is needed."])
G('fluids-b', 'Fluid properties', "Density is mass per volume. Specific weight is weight per volume, which is density times gravity. Specific gravity compares a fluid's density with water's. || Viscosity is a fluid's resistance to flowing: honey has a high viscosity and water a low one. Dynamic viscosity links shear stress to how fast one layer slides over the next. Kinematic viscosity is dynamic viscosity divided by density. The Reynolds number compares inertia with viscosity and tells you whether pipe flow is smooth (laminar, below about 2,100) or churning (turbulent).",
  [('Specific weight', "specific weight = density × g"), ('Specific gravity', r"SG = \frac{density}{density of water}"), ('Kinematic viscosity', r"\frac{dynamic viscosity}{density}"), ('Reynolds number', r"Re = \frac{VD}{kinematic viscosity}")],
  ("Oil with a kinematic viscosity of 4 × 10^{-5} m^{2}/s flows at 0.8 m/s in a 50 mm pipe. Is the flow laminar?", r"Re = \frac{0.8(0.05)}{4 × 10^{-5}} = 1,000. || That is below 2,100, so the flow is laminar.", 1000, "0.8*0.05/4e-5"),
  ["Confusing dynamic and kinematic viscosity. Check the units: Pa·s versus m^{2}/s."])
G('fluids-c', 'Fluid statics', "In a fluid at rest, pressure depends only on depth and acts equally in all directions. It increases by the specific weight for every unit of depth. Gauge pressure is measured from atmospheric; absolute pressure includes the atmosphere. || A manometer reads pressure as the height of a liquid column: move through it adding pressure going down and subtracting going up. The force on a submerged flat surface equals the pressure at the surface's centroid times its area, and it acts below the centroid. A floating or submerged body is pushed up by a force equal to the weight of fluid it displaces.",
  [('Pressure at depth', "p = specific weight × h"), ('Force on a plane surface', "F = specific weight × h_{c} × A"), ('Centre of pressure', r"y_{cp} = y_{c} + \frac{I_{c}}{y_{c}A}"), ('Buoyancy', "F_{b} = specific weight × displaced volume")],
  ("Find the gauge pressure at the bottom of a 5 m deep tank of oil with a specific gravity of 0.9.", "p = 0.9(9.81)(5) = 44.1 kPa.", 44.1, "0.9*gw*5"),
  ["Using the depth to the top of a surface instead of the depth to its centroid.", "Mixing gauge and absolute pressures in one equation."])
G('fluids-d', 'Energy, impulse and momentum', "Three conservation laws solve most flow problems. Continuity: what flows in must flow out, so velocity rises where the pipe narrows. Energy: along a flow, pressure head, velocity head and elevation head add to a constant, less any losses. Momentum: a force is needed to change the speed or direction of a flow. || Add pump head as an energy gain and friction as a loss. Friction loss in pipes comes from the Darcy-Weisbach equation with a friction factor from the Moody diagram. The energy grade line shows total head; the hydraulic grade line sits below it by the velocity head.",
  [('Continuity', "Q = A_{1}V_{1} = A_{2}V_{2}"), ('Energy equation', r"\frac{p_{1}}{specific weight} + \frac{V_{1}^{2}}{2g} + z_{1} + h_{pump} = \frac{p_{2}}{specific weight} + \frac{V_{2}^{2}}{2g} + z_{2} + h_{loss}"), ('Darcy-Weisbach', r"h_{f} = f\frac{L}{D}\frac{V^{2}}{2g}"), ('Momentum', "F = density × Q × (change in velocity)")],
  ("Water flows at 0.03 m^{3}/s through a 150 mm pipe. Find the velocity and the velocity head.", r"A = 0.01767 m^{2}, so V = \frac{0.03}{0.01767} = 1.70 m/s. || Velocity head = \frac{1.70^{2}}{2(9.81)} = 0.147 m.", 1.70, "0.03/(pi*0.15**2/4)"),
  ["Forgetting that halving the diameter quarters the area and quadruples the velocity.", "Putting a head loss on the wrong side of the energy equation."])
# ============ Surveying ============
G('surveying-a', 'Angles, distances and trigonometry', "Surveying measures angles and distances and turns them into positions. Directions are written two ways. An azimuth is one angle from 0° to 360°, clockwise from north. A bearing is an angle up to 90° from north or south toward east or west, such as S 35° W. || Distances measured along a slope must be reduced to horizontal. The interior angles of a closed traverse with n sides should add to (n - 2) × 180°; the shortfall or excess is the misclosure and is spread among the angles.",
  [('Horizontal distance', "H = slope distance × cos(vertical angle)"), ('Interior angle sum', "(n - 2) × 180°"), ('Law of sines', r"\frac{a}{sin A} = \frac{b}{sin B}")],
  ("Convert an azimuth of 200° to a bearing.", "200° is 20° past south, on the west side. || Bearing = S 20° W.", 20, "200 - 180"),
  ["Measuring a bearing from the east-west line. Bearings are always from north or south."])
G('surveying-b', 'Area computations', "Land area is computed from the coordinates of the corners or from measured offsets. The coordinate method cross-multiplies around the boundary and halves the result. For irregular boundaries, offsets measured at regular intervals are summed by the trapezoidal rule or Simpson's rule. || A triangle's area follows from two sides and the included angle, or from all three sides. Areas are often wanted in hectares (10,000 m^{2}) or acres (43,560 ft^{2}).",
  [('Area by coordinates', r"A = \frac{1}{2}|sum of (x_{i}y_{i+1} - x_{i+1}y_{i})|"), ('Triangle', r"A = \frac{1}{2}ab sin C"), ('Trapezoidal rule', r"A = w(\frac{h_{1} + h_{n}}{2} + h_{2} + ... + h_{n-1})")],
  ("Find the area of a triangle with corners at (0, 0), (40, 0) and (0, 30) metres.", r"A = \frac{1}{2}(40)(30) = 600 m^{2}.", 600, "0.5*40*30"),
  ["Listing the corners out of order around the boundary.", "Forgetting to halve the cross-multiplied sum."])
G('surveying-c', 'Earthwork and volume computations', "Earthwork volume is found from cross-sections cut along the route. The average end area method multiplies the mean of two neighbouring cross-section areas by the distance between them. It slightly overestimates when the sections differ a lot. The prismoidal formula is more exact because it also uses the middle section. || For pits and building sites, a grid of cut depths gives volume as plan area times average depth. Soil swells when dug and shrinks when compacted, so bank, loose and compacted volumes differ.",
  [('Average end area', r"V = L\frac{A_{1} + A_{2}}{2}"), ('Prismoidal formula', r"V = \frac{L}{6}(A_{1} + 4A_{m} + A_{2})"), ('Swell', "loose volume = bank volume × (1 + swell)")],
  ("Stations 30 m apart have fill areas of 18 m^{2} and 26 m^{2}. Find the fill volume.", r"V = 30 × \frac{18 + 26}{2} = 660 m^{3}.", 660, "30*(18+26)/2"),
  ["Adding cut and fill together. Keep them separate."])
G('surveying-d', 'Coordinate systems', "Positions are recorded as northings and eastings on a plane grid, such as a state plane system, or as latitude and longitude on the curved earth. State plane coordinates flatten a zone of the earth so that ordinary plane geometry works within small errors. || Each traverse line has a latitude (its north-south part) and a departure (its east-west part). Add them to the coordinates of the starting point to get the next point. In a closed traverse the latitudes and the departures should each add to zero; what is left is the error of closure.",
  [('Latitude of a line', "L cos(azimuth)"), ('Departure of a line', "L sin(azimuth)"), ('Distance from coordinates', r"\sqrt{(change in N)^{2} + (change in E)^{2}}"), ('Azimuth from coordinates', r"tan^{-1}(\frac{change in E}{change in N})")],
  ("A line runs 150 m at an azimuth of 120°. Find its latitude and departure.", "Latitude = 150 cos 120° = -75.0 m (south). || Departure = 150 sin 120° = 129.9 m (east).", 129.9, "150*sin(rad(120))"),
  ["Swapping sine and cosine: with azimuths from north, cosine gives the north part."])
G('surveying-e', 'Leveling', "Leveling finds elevations with a level and a graduated rod. The instrument gives a horizontal line of sight. A backsight on a point of known elevation gives the height of the instrument. A foresight on a new point is subtracted to give its elevation. || Carry elevations forward through turning points and close on a known benchmark to check the work. Grade is rise over run, usually as a percent.",
  [('Height of instrument', "HI = known elevation + backsight"), ('New elevation', "elevation = HI - foresight"), ('Percent grade', r"\frac{rise}{run} × 100")],
  ("From a benchmark at 50.00 m, the backsight is 2.10 m and the foresight on point A is 0.85 m. Find the elevation of A.", "HI = 50.00 + 2.10 = 52.10 m. || Elevation of A = 52.10 - 0.85 = 51.25 m.", 51.25, "50 + 2.10 - 0.85"),
  ["Adding the foresight instead of subtracting it."])
# ============ Water Resources and Environmental Engineering ============
G('water-a', 'Basic hydrology', "Hydrology follows rain from the sky to the stream. Some rain is caught by plants, some soaks in (infiltration), and the rest runs off. The share that runs off depends on the surface: pavement sheds nearly all of it, and forest very little. || The rational method estimates the peak flow from a small catchment using a runoff coefficient, the rainfall intensity for a storm lasting as long as the time of concentration, and the area. The NRCS curve number method estimates the depth of runoff from a storm. A hydrograph plots flow against time.",
  [('Rational method (USCS)', "Q = CiA (cfs, in/h, acres)"), ('NRCS storage', r"S = \frac{1,000}{CN} - 10"), ('NRCS runoff depth', r"Q = \frac{(P - 0.2S)^{2}}{P + 0.8S}")],
  ("A 5 acre site with C = 0.4 receives rain at 3 in/h. Find the peak runoff.", "Q = 0.4(3)(5) = 6 cfs.", 6, "0.4*3*5"),
  ["Using a rainfall intensity for the wrong storm duration. It should match the time of concentration."])
G('water-b', 'Basic hydraulics', "Open channels flow with a free surface, driven by gravity down the slope and resisted by friction on the bed and banks. Manning's equation gives the velocity from the roughness, the hydraulic radius (flow area divided by wetted perimeter) and the slope. || Specific energy is depth plus velocity head. Critical depth is the depth of least energy for a given flow. Flow shallower and faster than critical is supercritical; deeper and slower is subcritical. The Froude number tells which: below 1 is subcritical. A hydraulic jump is the abrupt change from supercritical to subcritical.",
  [("Manning's equation (SI)", r"V = \frac{1}{n}R^{2/3}S^{1/2}"), ('Hydraulic radius', r"R = \frac{A}{P}"), ('Critical depth, rectangular', r"y_{c} = (\frac{q^{2}}{g})^{1/3}"), ('Froude number', r"Fr = \frac{V}{\sqrt{gy}}")],
  ("A rectangular channel 2 m wide flows 0.5 m deep. Find its hydraulic radius.", r"A = 1.0 m^{2}. P = 2 + 2(0.5) = 3.0 m. || R = \frac{1.0}{3.0} = 0.333 m.", 0.333, "(2*0.5)/(2 + 2*0.5)"),
  ["Including the free water surface in the wetted perimeter.", "Using the USCS constant 1.49 with SI units."])
G('water-c', 'Pumps', "A pump adds energy to water, measured as head: the height it could lift the water. The power delivered to the water is specific weight times flow times head. The motor must supply more than that because no pump is perfectly efficient. || A pump curve shows the head a pump produces at each flow. The system curve shows the head the piping needs. They cross at the operating point. The affinity laws predict the effect of changing speed: flow changes in proportion, head with the square and power with the cube. Too little pressure at the inlet causes cavitation, so the available net positive suction head must exceed what the pump requires.",
  [('Water power', "P = specific weight × Q × H"), ('Input power', r"P_{in} = \frac{specific weight × Q × H}{efficiency}"), ('Affinity laws', r"\frac{Q_{2}}{Q_{1}} = \frac{N_{2}}{N_{1}}, \frac{H_{2}}{H_{1}} = (\frac{N_{2}}{N_{1}})^{2}, \frac{P_{2}}{P_{1}} = (\frac{N_{2}}{N_{1}})^{3}")],
  ("A pump lifts 0.02 m^{3}/s through 25 m at 80% efficiency. Find the input power.", r"Water power = 9.81(0.02)(25) = 4.9 kW. || Input = \frac{4.9}{0.80} = 6.13 kW.", 6.13, "gw*0.02*25/0.8"),
  ["Multiplying by efficiency instead of dividing when finding input power."])
G('water-d', 'Water distribution systems', "A distribution system delivers treated water at adequate pressure to every tap and hydrant. It is sized for demand that swings through the day and the year: average day, maximum day, peak hour, plus fire flow. Storage tanks even out the swings and keep pressure up by elevation. || Head loss in pipes is found with the Hazen-Williams or Darcy-Weisbach equations. Pipes in series carry the same flow and their head losses add. Pipes in parallel share the flow so that the head loss is the same in each. Static pressure comes from the height of the water surface above the point.",
  [('Static pressure', "p = specific weight × height"), ('Maximum-day demand', "average demand × peaking factor"), ('Pipes in series', "h_{total} = h_{1} + h_{2}"), ('Pipes in parallel', "Q_{total} = Q_{1} + Q_{2}, with h_{1} = h_{2}")],
  ("A tank's water surface is 30 m above a tap. Find the static pressure at the tap.", "p = 9.81(30) = 294 kPa.", 294, "gw*30"),
  ["Adding flows for pipes in series, or head losses for pipes in parallel."])
G('water-e', 'Flood control', "Floods are described by how often they are expected. A 100-year flood has a 1 in 100 chance of being equalled or exceeded in any year. It can happen two years running. Over a project's life, the chance of at least one such flood is far larger than the yearly chance. || Dams and reservoirs store flood water and release it slowly. Routing tracks a flood wave through a reservoir or river reach using inflow minus outflow equals change in storage. Spillways pass floods safely around a dam, and levees and floodways confine or divert the flow.",
  [('Annual exceedance probability', r"p = \frac{1}{T}"), ('Risk over n years', "1 - (1 - p)^{n}"), ('Storage routing', "inflow - outflow = change in storage per unit time")],
  ("What is the chance of at least one 100-year flood during a 30-year mortgage?", "Risk = 1 - (0.99)^{30} = 1 - 0.740 = 0.26, about one in four.", 0.26, "1 - 0.99**30"),
  ["Reading a 100-year flood as one that comes exactly once a century."])
G('water-f', 'Stormwater', "Development replaces soil and plants with roofs and pavement, so more rain runs off and it arrives faster. Stormwater design limits the damage. Detention basins hold runoff and release it slowly, cutting the peak. Retention basins hold it until it soaks in or evaporates. || Basin sizing is a bookkeeping exercise: storage rises when inflow exceeds outflow. Water quality practices such as swales, filters and settling capture the first flush, which carries most of the pollutants.",
  [('Storage change', "change in storage = (inflow - outflow) × time"), ('Rational peak flow', "Q = CiA")],
  ("A basin receives 2.5 m^{3}/s and releases 0.5 m^{3}/s for 15 minutes. Find the volume stored.", "Storage = (2.5 - 0.5)(900 s) = 1,800 m^{3}.", 1800, "(2.5-0.5)*15*60"),
  ["Forgetting to convert minutes to seconds."])
G('water-g', 'Collection systems', "Sewers carry wastewater and stormwater by gravity in pipes that usually flow partly full. They are designed like open channels with Manning's equation. The slope must give enough velocity to keep solids moving, typically at least 0.6 m/s (2 ft/s) when flowing full. || Design flow is the average flow times a peaking factor, plus an allowance for groundwater and rain leaking in (infiltration and inflow). For a circular pipe flowing full, the hydraulic radius is a quarter of the diameter.",
  [("Manning's equation", r"V = \frac{1}{n}R^{2/3}S^{1/2}"), ('Full circular pipe', r"R = \frac{D}{4}"), ('Peak flow', "average flow × peaking factor")],
  ("A sewer serves 5,000 people at 250 L per person per day with a peaking factor of 3.5. Find the peak flow in L/s.", r"Average = \frac{5,000(250)}{86,400} = 14.5 L/s. || Peak = 3.5(14.5) = 50.6 L/s.", 50.6, "5000*250/86400*3.5"),
  ["Using the diameter as the hydraulic radius."])
G('water-h', 'Groundwater', "Groundwater fills the gaps between soil grains below the water table. An aquifer is a layer that holds and passes useful amounts of water. Darcy's law says flow is proportional to the hydraulic conductivity of the soil and the slope of the water table (the hydraulic gradient). || The Darcy velocity is the flow per unit of total cross-section. The water itself moves faster because it only travels through the pores: divide by porosity for the seepage velocity. Pumping a well draws the water table down into a cone of depression.",
  [("Darcy's law", "Q = KiA"), ('Hydraulic gradient', r"i = \frac{head difference}{flow length}"), ('Seepage velocity', r"v_{s} = \frac{Ki}{porosity}"), ('Unconfined well', r"Q = \frac{π K(h_{2}^{2} - h_{1}^{2})}{ln(r_{2}/r_{1})}")],
  ("An aquifer has K = 20 m/day. Heads at two wells 500 m apart differ by 2 m. Find the Darcy velocity.", r"i = \frac{2}{500} = 0.004. || v = Ki = 20(0.004) = 0.08 m/day.", 0.08, "20*2/500"),
  ["Confusing Darcy velocity with seepage velocity."])
G('water-i', 'Water quality', "Water quality is described by what is dissolved or suspended in the water. Dissolved oxygen keeps streams alive. Biochemical oxygen demand (BOD) is the oxygen that bacteria use up while breaking down organic waste: high BOD starves a stream of oxygen. || Hardness is mainly calcium and magnesium and is reported as an equivalent amount of calcium carbonate. Alkalinity is the water's capacity to neutralize acid. pH measures acidity. Turbidity measures cloudiness. Concentrations convert to equivalents by dividing by the equivalent weight.",
  [('BOD from a diluted sample', r"BOD = \frac{DO_{initial} - DO_{final}}{dilution fraction}"), ('BOD exerted over time', "BOD_{t} = L(1 - e^{-kt})"), ('As CaCO_{3}', r"mg/L × \frac{50}{equivalent weight}")],
  ("A 10 mL sample diluted to 300 mL loses 4.0 mg/L of dissolved oxygen in five days. Find the BOD_{5}.", r"Dilution fraction = \frac{10}{300}. || BOD_{5} = \frac{4.0}{10/300} = 120 mg/L.", 120, "4.0/(10/300)"),
  ["Forgetting to divide by the dilution fraction."])
G('water-j', 'Testing and standards', "Standards set the limits that water, wastewater, air and noise must meet, and standard tests check compliance. For drinking water, the maximum contaminant level (MCL) is the enforceable limit and the MCLG is the health goal. Wastewater discharges are limited by permit for BOD, suspended solids and other measures. || Air quality standards limit pollutants such as particulates and ozone. Noise is measured in decibels, a logarithmic scale: two equal sources together are 3 dB louder than one, and ten are 10 dB louder.",
  [('Combining sound levels', "L = 10 log(sum of 10^{L_{i}/10})"), ('Mass loading', "mass per day = concentration × flow")],
  ("Three identical machines each produce 70 dB. Find the combined level.", "L = 10 log(3 × 10^{7}) = 74.8 dB.", 74.8, "10*log10(3*10**7)"),
  ["Adding decibel values directly."])
G('water-k', 'Water and wastewater treatment', "Drinking water treatment removes particles and kills germs. Coagulation and flocculation make fine particles clump, sedimentation lets the clumps settle, filtration strains out the rest, and disinfection kills what remains. Softening removes hardness. || Wastewater treatment removes solids and organic matter. Primary treatment settles solids. Secondary treatment uses bacteria, as in activated sludge, to consume dissolved organic matter. Tanks are sized by detention time (volume over flow) and by surface overflow rate (flow over surface area). Chemical feed is dose times flow.",
  [('Detention time', r"t = \frac{V}{Q}"), ('Surface overflow rate', r"\frac{Q}{surface area}"), ('Chemical feed', "mass per day = dose × Q"), ('Removal efficiency', r"\frac{in - out}{in} × 100")],
  ("A 600 m^{3} tank treats 4,800 m^{3}/day. Find the detention time in hours.", r"t = \frac{600}{4,800} = 0.125 day = 3.0 h.", 3.0, "600/4800*24"),
  ["Leaving detention time in days when hours are asked.", "A dose of 1 mg/L equals 1 g/m^{3}, or 1 kg per 1,000 m^{3}."])
save()
